arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

:root {
  --primary: #1868DB;
  --primary-dark: #1255B8;
  --primary-light: #E8F0FE;
  --accent: #FF613D;
  --accent-hover: #E5512F;
  --dark: #292A2E;
  --dark-light: #3D3E42;
  --gray-900: #1A1A1E;
  --gray-700: #4A4B50;
  --gray-500: #6E7078;
  --gray-400: #9194A0;
  --gray-300: #C4C7D0;
  --gray-200: #E2E4EA;
  --gray-100: #F0F2F5;
  --gray-50: #F8F9FC;
  --white: #FFFFFF;
  --success: #22C55E;
  --warning: #F59E0B;
  --gradient-primary: linear-gradient(135deg, #1868DB 0%, #6C3AED 100%);
  --gradient-hero: linear-gradient(160deg, #F8F9FC 0%, #E8F0FE 50%, #EDE9FE 100%);
  --gradient-section: linear-gradient(180deg, #F8F9FC 0%, #FFFFFF 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 50px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --transition: 0.2s ease;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--dark);
  background: var(--white);
}

img, svg { max-width: 100%; display: block; }
a { color: var(--primary); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--primary-dark); }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== TYPOGRAPHY ===== */
h1 { font-size: 3.5rem; font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; }
h3 { font-size: 1.5rem; font-weight: 600; line-height: 1.3; }
h4 { font-size: 1.25rem; font-weight: 600; line-height: 1.4; }
p { color: var(--gray-700); line-height: 1.7; }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px; border-radius: var(--radius-full); font-size: 1rem;
  font-weight: 600; transition: all var(--transition); white-space: nowrap;
}
.btn-primary { background: var(--primary); color: var(--white); }
.btn-primary:hover { background: var(--primary-dark); color: var(--white); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-accent { background: var(--accent); color: var(--white); }
.btn-accent:hover { background: var(--accent-hover); color: var(--white); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-outline { background: transparent; color: var(--primary); border: 2px solid var(--primary); }
.btn-outline:hover { background: var(--primary); color: var(--white); }
.btn-white { background: var(--white); color: var(--primary); }
.btn-white:hover { background: var(--gray-50); color: var(--primary); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn-dark { background: var(--dark); color: var(--white); }
.btn-dark:hover { background: var(--gray-900); color: var(--white); transform: translateY(-1px); }
.btn-ghost { background: transparent; color: var(--gray-700); padding: 8px 16px; }
.btn-ghost:hover { color: var(--primary); background: var(--primary-light); }
.btn-lg { padding: 16px 36px; font-size: 1.1rem; }
.btn-sm { padding: 8px 20px; font-size: 0.875rem; }

/* ===== NAVIGATION ===== */
.navbar {
  position: sticky; top: 0; z-index: 1000; background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px); border-bottom: 1px solid var(--gray-200);
  padding: 0 24px; height: 72px;
}
.navbar .container { display: flex; align-items: center; justify-content: space-between; height: 100%; }
.nav-logo { font-size: 1.5rem; font-weight: 800; color: var(--dark); display: flex; align-items: center; gap: 8px; }
.nav-logo svg { width: 32px; height: 32px; }
.nav-links { display: flex; align-items: center; gap: 8px; }
.nav-links a { padding: 8px 16px; border-radius: var(--radius-full); color: var(--gray-700); font-weight: 500; font-size: 0.95rem; transition: all var(--transition); }
.nav-links a:hover { color: var(--primary); background: var(--primary-light); }
.nav-actions { display: flex; align-items: center; gap: 12px; }
.mobile-toggle { display: none; width: 40px; height: 40px; align-items: center; justify-content: center; border-radius: var(--radius-sm); }
.mobile-toggle span { display: block; width: 22px; height: 2px; background: var(--dark); position: relative; transition: all var(--transition); }
.mobile-toggle span::before, .mobile-toggle span::after {
  content: ''; position: absolute; width: 22px; height: 2px; background: var(--dark); transition: all var(--transition);
}
.mobile-toggle span::before { top: -7px; }
.mobile-toggle span::after { top: 7px; }
.mobile-menu { display: none; }

/* ===== HERO ===== */
.hero { padding: 100px 0 80px; background: var(--gradient-hero); text-align: center; overflow: hidden; }
.hero h1 { max-width: 800px; margin: 0 auto 24px; }
.hero p { max-width: 600px; margin: 0 auto 40px; font-size: 1.2rem; color: var(--gray-500); }
.hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
.hero-visual {
  max-width: 900px; margin: 60px auto 0; border-radius: var(--radius-lg);
  background: var(--white); box-shadow: var(--shadow-xl); overflow: hidden;
  aspect-ratio: 16/9; display: flex; align-items: center; justify-content: center;
  border: 1px solid var(--gray-200);
}
.hero-visual-placeholder {
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  color: var(--gray-400); padding: 40px;
}
.hero-visual-placeholder svg { width: 64px; height: 64px; opacity: 0.4; }

/* ===== LOGO BAR ===== */
.logo-bar { padding: 60px 0; text-align: center; }
.logo-bar p { font-size: 0.95rem; color: var(--gray-400); margin-bottom: 32px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.05em; }
.logo-grid {
  display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap;
  opacity: 0.5; filter: grayscale(100%);
}
.logo-grid span { font-size: 1.25rem; font-weight: 700; color: var(--gray-700); white-space: nowrap; }

/* ===== SECTIONS ===== */
.section { padding: 100px 0; }
.section-alt { background: var(--gray-50); }
.section-dark { background: var(--dark); color: var(--white); }
.section-dark p { color: var(--gray-300); }
.section-dark h2, .section-dark h3 { color: var(--white); }
.section-header { text-align: center; max-width: 700px; margin: 0 auto 60px; }
.section-header p { margin-top: 16px; font-size: 1.1rem; }

.badge {
  display: inline-flex; align-items: center; padding: 6px 14px;
  background: var(--accent); color: var(--white); border-radius: var(--radius-full);
  font-size: 0.8rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
  margin-bottom: 16px;
}
.badge-outline {
  background: transparent; border: 1px solid var(--primary); color: var(--primary);
}

/* ===== FEATURE SECTIONS ===== */
.feature-row {
  display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
}
.feature-row.reverse .feature-content { order: 2; }
.feature-row.reverse .feature-media { order: 1; }
.feature-content h2 { margin-bottom: 20px; }
.feature-content p { margin-bottom: 24px; }
.feature-media {
  background: var(--gray-50); border-radius: var(--radius-lg); padding: 40px;
  display: flex; align-items: center; justify-content: center; min-height: 360px;
  border: 1px solid var(--gray-200);
}
.feature-placeholder {
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  color: var(--gray-400);
}
.feature-placeholder svg { width: 48px; height: 48px; opacity: 0.4; }

/* ===== FEATURE LIST ===== */
.feature-list { display: flex; flex-direction: column; gap: 24px; }
.feature-list-item { display: flex; gap: 16px; }
.feature-list-icon {
  flex-shrink: 0; width: 44px; height: 44px; border-radius: var(--radius-md);
  background: var(--primary-light); display: flex; align-items: center; justify-content: center;
  color: var(--primary);
}
.feature-list-item h4 { margin-bottom: 6px; }
.feature-list-item p { font-size: 0.95rem; }

/* ===== FEATURES GRID ===== */
.features-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px;
}
.feature-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  padding: 28px; transition: all var(--transition);
}
.feature-card:hover { border-color: var(--primary); box-shadow: var(--shadow-md); transform: translateY(-2px); }
.feature-card-icon {
  width: 48px; height: 48px; border-radius: var(--radius-md);
  background: var(--primary-light); display: flex; align-items: center; justify-content: center;
  margin-bottom: 16px; color: var(--primary);
}
.feature-card h4 { margin-bottom: 8px; font-size: 1rem; }
.feature-card p { font-size: 0.9rem; color: var(--gray-500); }

/* ===== USE CASES ===== */
.use-cases-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.use-case-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  padding: 32px; text-align: center; transition: all var(--transition);
}
.use-case-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); border-color: var(--primary); }
.use-case-icon {
  width: 64px; height: 64px; border-radius: var(--radius-lg);
  background: var(--gradient-hero); display: flex; align-items: center; justify-content: center;
  margin: 0 auto 20px; font-size: 28px;
}
.use-case-card h4 { margin-bottom: 8px; }
.use-case-card p { font-size: 0.9rem; color: var(--gray-500); }

/* ===== STATS ===== */
.stats-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; text-align: center; }
.stat-item h3 { font-size: 3.5rem; font-weight: 800; color: var(--primary); margin-bottom: 8px; }
.stat-item p { font-size: 1.05rem; color: var(--gray-500); }

/* ===== TESTIMONIALS ===== */
.testimonials-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.testimonial-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  padding: 32px; transition: all var(--transition);
}
.testimonial-card:hover { box-shadow: var(--shadow-md); }
.testimonial-card blockquote { font-size: 0.95rem; line-height: 1.7; color: var(--gray-700); margin-bottom: 24px; font-style: italic; }
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.testimonial-avatar {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--gradient-primary); display: flex; align-items: center; justify-content: center;
  color: var(--white); font-weight: 700; font-size: 1rem;
}
.testimonial-info strong { display: block; font-size: 0.9rem; }
.testimonial-info span { font-size: 0.8rem; color: var(--gray-400); }

/* ===== PRICING ===== */
.pricing-toggle-wrapper { display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 20px; }
.pricing-toggle {
  position: relative; width: 56px; height: 30px; background: var(--gray-300);
  border-radius: var(--radius-full); cursor: pointer; transition: background var(--transition);
}
.pricing-toggle.active { background: var(--primary); }
.pricing-toggle-knob {
  position: absolute; top: 3px; left: 3px; width: 24px; height: 24px;
  background: var(--white); border-radius: 50%; transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}
.pricing-toggle.active .pricing-toggle-knob { transform: translateX(26px); }
.pricing-label { font-weight: 500; color: var(--gray-500); cursor: pointer; }
.pricing-label.active { color: var(--dark); font-weight: 600; }
.save-badge {
  background: var(--success); color: var(--white); font-size: 0.75rem;
  font-weight: 700; padding: 4px 10px; border-radius: var(--radius-full);
}

.team-slider-wrapper { text-align: center; margin-bottom: 48px; }
.team-slider-wrapper label { font-weight: 600; font-size: 1rem; color: var(--dark); }
.team-slider {
  width: 100%; max-width: 400px; margin: 16px auto 0; display: block;
  -webkit-appearance: none; appearance: none; height: 6px; background: var(--gray-200);
  border-radius: var(--radius-full); outline: none;
}
.team-slider::-webkit-slider-thumb {
  -webkit-appearance: none; width: 24px; height: 24px; background: var(--primary);
  border-radius: 50%; cursor: pointer; box-shadow: var(--shadow-md);
}
.team-slider::-moz-range-thumb {
  width: 24px; height: 24px; background: var(--primary);
  border-radius: 50%; cursor: pointer; border: none; box-shadow: var(--shadow-md);
}
.team-size-display { display: block; margin-top: 8px; font-size: 0.95rem; color: var(--gray-500); }

.pricing-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.pricing-card {
  background: var(--white); border: 2px solid var(--gray-200); border-radius: var(--radius-lg);
  padding: 32px; position: relative; transition: all var(--transition);
}
.pricing-card:hover { border-color: var(--primary); box-shadow: var(--shadow-lg); }
.pricing-card.popular { border-color: var(--primary); box-shadow: var(--shadow-lg); }
.pricing-card.popular::before {
  content: 'MOST POPULAR'; position: absolute; top: -14px; left: 50%; transform: translateX(-50%);
  background: var(--primary); color: var(--white); font-size: 0.7rem; font-weight: 700;
  padding: 4px 16px; border-radius: var(--radius-full); letter-spacing: 0.05em;
}
.pricing-card h3 { font-size: 1.25rem; margin-bottom: 8px; }
.pricing-card .price { font-size: 2.5rem; font-weight: 800; color: var(--dark); margin-bottom: 4px; }
.pricing-card .price span { font-size: 1rem; font-weight: 400; color: var(--gray-500); }
.pricing-card .price-note { font-size: 0.85rem; color: var(--gray-400); margin-bottom: 24px; }
.pricing-card ul { margin-bottom: 28px; display: flex; flex-direction: column; gap: 12px; }
.pricing-card ul li { display: flex; align-items: flex-start; gap: 10px; font-size: 0.9rem; color: var(--gray-700); }
.pricing-card ul li svg { flex-shrink: 0; width: 18px; height: 18px; color: var(--success); margin-top: 2px; }
.pricing-card .btn { width: 100%; }

/* ===== COMPARISON TABLE ===== */
.comparison-wrapper { overflow-x: auto; margin-top: 60px; }
.comparison-table { width: 100%; border-collapse: collapse; min-width: 700px; }
.comparison-table th, .comparison-table td { padding: 14px 16px; text-align: center; border-bottom: 1px solid var(--gray-200); font-size: 0.9rem; }
.comparison-table th { font-weight: 600; background: var(--gray-50); color: var(--dark); }
.comparison-table td:first-child, .comparison-table th:first-child { text-align: left; font-weight: 500; }
.comparison-table td.highlight { background: rgba(24,104,219,0.04); }
.comparison-table .check { color: var(--success); font-weight: 700; }
.comparison-table .dash { color: var(--gray-300); }
.comparison-toggle-btn {
  display: flex; align-items: center; gap: 8px; margin: 24px auto 0;
  color: var(--primary); font-weight: 600; font-size: 1rem; cursor: pointer; transition: all var(--transition);
}
.comparison-toggle-btn:hover { color: var(--primary-dark); }
.comparison-toggle-btn svg { transition: transform var(--transition); }
.comparison-toggle-btn.expanded svg { transform: rotate(180deg); }
.comparison-hidden { display: none; }
.comparison-hidden.show { display: table-row; }

/* ===== FAQ ===== */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  width: 100%; padding: 24px 0; font-size: 1.05rem; font-weight: 600;
  color: var(--dark); text-align: left; cursor: pointer; transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-question svg { flex-shrink: 0; width: 24px; height: 24px; transition: transform var(--transition); color: var(--gray-400); }
.faq-item.active .faq-question svg { transform: rotate(180deg); color: var(--primary); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.faq-answer-inner { padding: 0 0 24px; }
.faq-answer-inner p { font-size: 0.95rem; line-height: 1.8; }
.faq-item.active .faq-answer { max-height: 500px; }

/* ===== BLOG ===== */
.blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; }
.blog-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  overflow: hidden; transition: all var(--transition);
}
.blog-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.blog-card-image {
  height: 200px; background: var(--gradient-hero);
  display: flex; align-items: center; justify-content: center;
}
.blog-card-body { padding: 24px; }
.blog-card-body h4 { margin-bottom: 8px; }
.blog-card-body p { font-size: 0.9rem; color: var(--gray-500); margin-bottom: 16px; }
.blog-card-body a { font-weight: 600; font-size: 0.9rem; }

/* ===== CTA BANNER ===== */
.cta-banner { padding: 80px 0; background: var(--gradient-primary); text-align: center; color: var(--white); }
.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.8); margin-bottom: 32px; font-size: 1.1rem; }

/* ===== ENTERPRISE CTA ===== */
.enterprise-cta {
  background: var(--dark); border-radius: var(--radius-xl); padding: 60px;
  text-align: center; color: var(--white);
}
.enterprise-cta h2 { color: var(--white); margin-bottom: 12px; }
.enterprise-cta p { color: var(--gray-300); margin-bottom: 32px; }

/* ===== INTEGRATIONS ===== */
.integrations-grid {
  display: flex; flex-wrap: wrap; gap: 16px; justify-content: center; max-width: 700px; margin: 0 auto;
}
.integration-chip {
  display: flex; align-items: center; gap: 8px; padding: 10px 20px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-full);
  font-size: 0.9rem; font-weight: 500; color: var(--gray-700); transition: all var(--transition);
}
.integration-chip:hover { border-color: var(--primary); box-shadow: var(--shadow-sm); }

/* ===== SECURITY ===== */
.security-features { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.security-item {
  display: flex; align-items: flex-start; gap: 16px; padding: 24px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
}
.security-icon {
  flex-shrink: 0; width: 44px; height: 44px; border-radius: var(--radius-md);
  background: var(--primary-light); display: flex; align-items: center; justify-content: center;
  color: var(--primary);
}
.security-item h4 { margin-bottom: 4px; font-size: 0.95rem; }
.security-item p { font-size: 0.85rem; }

/* ===== FOOTER ===== */
.footer { background: var(--gray-900); color: var(--gray-300); padding: 80px 0 40px; }
.footer-grid { display: grid; grid-template-columns: 2fr repeat(5, 1fr); gap: 40px; margin-bottom: 60px; }
.footer-brand p { font-size: 0.9rem; margin-top: 12px; line-height: 1.7; }
.footer-col h5 { color: var(--white); font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 16px; }
.footer-col a { display: block; font-size: 0.85rem; color: var(--gray-400); padding: 4px 0; transition: color var(--transition); }
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--dark-light); padding-top: 24px;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.8rem; color: var(--gray-500); }
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a { font-size: 0.8rem; color: var(--gray-500); }
.footer-bottom-links a:hover { color: var(--white); }

/* ===== AUTH PAGES ===== */
.auth-page { min-height: 100vh; display: flex; }
.auth-main { flex: 1; display: flex; align-items: center; justify-content: center; padding: 40px; }
.auth-sidebar {
  width: 480px; background: var(--gradient-hero); display: flex; align-items: center;
  justify-content: center; padding: 60px; border-left: 1px solid var(--gray-200);
}
.auth-card { width: 100%; max-width: 420px; }
.auth-card .nav-logo { margin-bottom: 40px; font-size: 1.75rem; justify-content: center; }
.auth-card h1 { font-size: 1.75rem; text-align: center; margin-bottom: 32px; }
.social-buttons { display: flex; flex-direction: column; gap: 12px; margin-bottom: 24px; }
.social-btn {
  display: flex; align-items: center; justify-content: center; gap: 12px;
  width: 100%; padding: 12px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm);
  font-size: 0.95rem; font-weight: 500; color: var(--dark); background: var(--white);
  transition: all var(--transition);
}
.social-btn:hover { background: var(--gray-50); border-color: var(--gray-300); }
.social-btn svg { width: 20px; height: 20px; }
.auth-divider { display: flex; align-items: center; gap: 16px; margin: 24px 0; }
.auth-divider span { font-size: 0.85rem; color: var(--gray-400); white-space: nowrap; }
.auth-divider::before, .auth-divider::after { content: ''; flex: 1; height: 1px; background: var(--gray-200); }
.auth-input-group { margin-bottom: 16px; }
.auth-input-group label { display: block; font-size: 0.9rem; font-weight: 500; margin-bottom: 6px; }
.auth-input {
  width: 100%; padding: 12px 16px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm);
