.logo-bar p { font-size: 0.95rem; color: var(--gray-400); margin-bottom: 32px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.05em; }
.logo-grid {
  display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap;
  opacity: 0.5; filter: grayscale(100%);
}
