.comparison-toggle-btn:hover { color: var(--primary-dark); }
.comparison-toggle-btn svg { transition: transform var(--transition); }
.comparison-toggle-btn.expanded svg { transform: rotate(180deg); }
.comparison-hidden { display: none; }
.comparison-hidden.show { display: table-row; }

/* ===== FAQ ===== */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-question {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  width: 100%; padding: 24px 0; font-size: 1.05rem; font-weight: 600;
  color: var(--dark); text-align: left; cursor: pointer; transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-question svg { flex-shrink: 0; width: 24px; height: 24px; transition: transform var(--transition); color: var(--gray-400); }
.faq-item.active .faq-question svg { transform: rotate(180deg); color: var(--primary); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.faq-answer-inner { padding: 0 0 24px; }
.faq-answer-inner p { font-size: 0.95rem; line-height: 1.8; }
.faq-item.active .faq-answer { max-height: 500px; }

/* ===== BLOG ===== */
.blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; }
.blog-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  overflow: hidden; transition: all var(--transition);
}
.blog-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.blog-card-image {
  height: 200px; background: var(--gradient-hero);
  display: flex; align-items: center; justify-content: center;
}
.blog-card-body { padding: 24px; }
.blog-card-body h4 { margin-bottom: 8px; }
.blog-card-body p { font-size: 0.9rem; color: var(--gray-500); margin-bottom: 16px; }
.blog-card-body a { font-weight: 600; font-size: 0.9rem; }

/* ===== CTA BANNER ===== */
.cta-banner { padding: 80px 0; background: var(--gradient-primary); text-align: center; color: var(--white); }
.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.8); margin-bottom: 32px; font-size: 1.1rem; }

/* ===== ENTERPRISE CTA ===== */
.enterprise-cta {
  background: var(--dark); border-radius: var(--radius-xl); padding: 60px;
  text-align: center; color: var(--white);
}
.enterprise-cta h2 { color: var(--white); margin-bottom: 12px; }
.enterprise-cta p { color: var(--gray-300); margin-bottom: 32px; }

/* ===== INTEGRATIONS ===== */
.integrations-grid {
  display: flex; flex-wrap: wrap; gap: 16px; justify-content: center; max-width: 700px; margin: 0 auto;
}
.integration-chip {
  display: flex; align-items: center; gap: 8px; padding: 10px 20px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-full);
  font-size: 0.9rem; font-weight: 500; color: var(--gray-700); transition: all var(--transition);
}
.integration-chip:hover { border-color: var(--primary); box-shadow: var(--shadow-sm); }

/* ===== SECURITY ===== */
.security-features { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.security-item {
  display: flex; align-items: flex-start; gap: 16px; padding: 24px;
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
}
.security-icon {
  flex-shrink: 0; width: 44px; height: 44px; border-radius: var(--radius-md);
  background: var(--primary-light); display: flex; align-items: center; justify-content: center;
  color: var(--primary);
}
.security-item h4 { margin-bottom: 4px; font-size: 0.95rem; }
.security-item p { font-size: 0.85rem; }

/* ===== FOOTER ===== */
.footer { background: var(--gray-900); color: var(--gray-300); padding: 80px 0 40px; }
.footer-grid { display: grid; grid-template-columns: 2fr repeat(5, 1fr); gap: 40px; margin-bottom: 60px; }
.footer-brand p { font-size: 0.9rem; margin-top: 12px; line-height: 1.7; }
.footer-col h5 { color: var(--white); font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 16px; }
.footer-col a { display: block; font-size: 0.85rem; color: var(--gray-400); padding: 4px 0; transition: color var(--transition); }
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid var(--dark-light); padding-top: 24px;
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.8rem; color: var(--gray-500); }
.footer-bottom-links { display: flex; gap: 24px; }
.footer-bottom-links a { font-size: 0.8rem; color: var(--gray-500); }
.footer-bottom-links a:hover { color: var(--white); }

/* ===== AUTH PAGES ===== */
.auth-page { min-height: 100vh; display: flex; }
.auth-main { flex: 1; display: flex; align-items: center; justify-content: center; padding: 40px; }
.auth-sidebar {
  width: 480px; background: var(--gradient-hero); display: flex; align-items: center;
  justify-content: center; padding: 60px; border-left: 1px solid var(--gray-200);
}
.auth-card { width: 100%; max-width: 420px; }
.auth-card .nav-logo { margin-bottom: 40px; font-size: 1.75rem; justify-content: center; }
.auth-card h1 { font-size: 1.75rem; text-align: center; margin-bottom: 32px; }
.social-buttons { display: flex; flex-direction: column; gap: 12px; margin-bottom: 24px; }
.social-btn {
  display: flex; align-items: center; justify-content: center; gap: 12px;
  width: 100%; padding: 12px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm);
  font-size: 0.95rem; font-weight: 500; color: var(--dark); background: var(--white);
  transition: all var(--transition);
}
.social-btn:hover { background: var(--gray-50); border-color: var(--gray-300); }
.social-btn svg { width: 20px; height: 20px; }
.auth-divider { display: flex; align-items: center; gap: 16px; margin: 24px 0; }
.auth-divider span { font-size: 0.85rem; color: var(--gray-400); white-space: nowrap; }
.auth-divider::before, .auth-divider::after { content: ''; flex: 1; height: 1px; background: var(--gray-200); }
.auth-input-group { margin-bottom: 16px; }
.auth-input-group label { display: block; font-size: 0.9rem; font-weight: 500; margin-bottom: 6px; }
.auth-input {
  width: 100%; padding: 12px 16px; border: 1px solid var(--gray-200); border-radius: var(--radius-sm);
  font-size: 1rem; transition: border-color var(--transition); outline: none;
}
.auth-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(24,104,219,0.1); }
.auth-footer { text-align: center; margin-top: 24px; font-size: 0.8rem; color: var(--gray-400); line-height: 1.6; }
.auth-footer a { color: var(--primary); }
.auth-switch { text-align: center; margin-top: 16px; font-size: 0.9rem; color: var(--gray-500); }
.auth-switch a { font-weight: 600; }

.sidebar-testimonial { max-width: 360px; }
.sidebar-testimonial blockquote { font-size: 1.1rem; line-height: 1.7; color: var(--gray-700); margin-bottom: 24px; font-style: italic; }
.sidebar-testimonial .testimonial-author strong { color: var(--dark); }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 9999;
  background: var(--white); border-top: 1px solid var(--gray-200);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1); padding: 20px 24px;
  transform: translateY(0); transition: transform 0.3s ease;
}
.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }
.cookie-inner { max-width: var(--max-width); margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.cookie-text { flex: 1; }
.cookie-text p { font-size: 0.9rem; color: var(--gray-700); margin: 0; }
.cookie-text a { color: var(--primary); font-weight: 500; }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

.cookie-modal-overlay {
  position: fixed; inset: 0; z-index: 10000; background: rgba(0,0,0,0.5);
  display: none; align-items: center; justify-content: center; padding: 24px;
}
.cookie-modal-overlay.show { display: flex; }
.cookie-modal {
  background: var(--white); border-radius: var(--radius-lg); padding: 36px;
  max-width: 560px; width: 100%; max-height: 90vh; overflow-y: auto;
}
.cookie-modal h3 { margin-bottom: 8px; }
.cookie-modal > p { font-size: 0.9rem; color: var(--gray-500); margin-bottom: 28px; }
.cookie-category { padding: 16px 0; border-bottom: 1px solid var(--gray-200); display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.cookie-category:last-of-type { border-bottom: none; }
.cookie-category-info h4 { font-size: 0.95rem; margin-bottom: 2px; }
.cookie-category-info p { font-size: 0.8rem; color: var(--gray-400); }
.toggle-switch {
  position: relative; width: 48px; height: 26px; background: var(--gray-300);
  border-radius: var(--radius-full); cursor: pointer; transition: background var(--transition); flex-shrink: 0;
}
.toggle-switch.active { background: var(--primary); }
.toggle-switch.disabled { opacity: 0.5; cursor: not-allowed; }
.toggle-switch-knob {
  position: absolute; top: 3px; left: 3px; width: 20px; height: 20px;
  background: var(--white); border-radius: 50%; transition: transform var(--transition);
}
.toggle-switch.active .toggle-switch-knob { transform: translateX(22px); }
.cookie-modal-actions { display: flex; gap: 12px; margin-top: 24px; }
.cookie-modal-actions .btn { flex: 1; }

/* ===== AI FEATURES ===== */
.ai-features-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.ai-feature-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  padding: 24px; position: relative;
}
.ai-feature-card .badge { margin-bottom: 12px; font-size: 0.65rem; padding: 3px 8px; }
.ai-feature-card h4 { font-size: 1rem; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  h1 { font-size: 2.75rem; }
  h2 { font-size: 2rem; }
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-cards { grid-template-columns: repeat(2, 1fr); }
  .testimonials-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .ai-features-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  h1 { font-size: 2.25rem; }
  h2 { font-size: 1.75rem; }
  .section { padding: 60px 0; }
  .hero { padding: 60px 0 40px; }
  .feature-row { grid-template-columns: 1fr; gap: 32px; }
  .feature-row.reverse .feature-content { order: 1; }
  .feature-row.reverse .feature-media { order: 2; }
  .features-grid { grid-template-columns: 1fr; }
  .use-cases-grid { grid-template-columns: 1fr 1fr; }
  .pricing-cards { grid-template-columns: 1fr; max-width: 440px; margin: 0 auto; }
  .stats-row { grid-template-columns: 1fr; gap: 24px; }
  .testimonials-grid { grid-template-columns: 1fr; }
  .blog-grid { grid-template-columns: 1fr; }
  .security-features { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .nav-links { display: none; }
  .nav-actions .btn-ghost, .nav-actions .btn-outline { display: none; }
  .mobile-toggle { display: flex; }
  .mobile-menu.open { display: block; position: fixed; top: 72px; left: 0; right: 0; background: var(--white); border-bottom: 1px solid var(--gray-200); padding: 24px; z-index: 999; box-shadow: var(--shadow-lg); }
  .mobile-menu.open a { display: block; padding: 12px 0; font-weight: 500; color: var(--dark); font-size: 1.1rem; }
  .mobile-menu.open .btn { width: 100%; margin-top: 16px; text-align: center; }
  .auth-sidebar { display: none; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .comparison-table { font-size: 0.8rem; }
  .comparison-table th, .comparison-table td { padding: 10px 8px; }
  .logo-grid { gap: 24px; }
  .enterprise-cta { padding: 40px 24px; }
  .ai-features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  h1 { font-size: 1.85rem; }
  .hero-actions { flex-direction: column; align-items: center; }
  .use-cases-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .cookie-actions { flex-direction: column; width: 100%; }
  .cookie-actions .btn { width: 100%; }
}
