.cookie-modal h3 { margin-bottom: 8px; }
.cookie-modal > p { font-size: 0.9rem; color: var(--gray-500); margin-bottom: 28px; }
.cookie-category { padding: 16px 0; border-bottom: 1px solid var(--gray-200); display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.cookie-category:last-of-type { border-bottom: none; }
.cookie-category-info h4 { font-size: 0.95rem; margin-bottom: 2px; }
.cookie-category-info p { font-size: 0.8rem; color: var(--gray-400); }
.toggle-switch {
  position: relative; width: 48px; height: 26px; background: var(--gray-300);
  border-radius: var(--radius-full); cursor: pointer; transition: background var(--transition); flex-shrink: 0;
