.toggle-switch.active .toggle-switch-knob { transform: translateX(22px); }
.cookie-modal-actions { display: flex; gap: 12px; margin-top: 24px; }
.cookie-modal-actions .btn { flex: 1; }

/* ===== AI FEATURES ===== */
.ai-features-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.ai-feature-card {
  background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md);
