### 10. Footer (same as home)
Standard footer with 6-column grid and footer-bottom.

## JavaScript (inline, at bottom before </body>)

### 1. Billing Toggle
```
const toggle = document.querySelector('.pricing-toggle');
const labels = document.querySelectorAll('.pricing-label');
let isAnnual = false;

// Monthly prices
const prices = { business: { monthly: 18, annual: 15 }, ai: { monthly: 24, annual: 20 } };

toggle.addEventListener('click', () => {
  isAnnual = !isAnnual;
  toggle.classList.toggle('active', isAnnual);
  labels[0].classList.toggle('active', !isAnnual);
  labels[1].classList.toggle('active', isAnnual);
  updatePrices();
});

labels.forEach((label, i) => {
  label.addEventListener('click', () => {
    isAnnual = i === 1;
    toggle.classList.toggle('active', isAnnual);
    labels[0].classList.toggle('active', !isAnnual);
    labels[1].classList.toggle('active', isAnnual);
    updatePrices();
  });
});

function updatePrices() {
  const period = isAnnual ? 'annual' : 'monthly';
  const billingNote = isAnnual ? 'billed annually' : 'billed monthly';
  // Update Business card price
  document.getElementById('business-price').textContent = '$' + prices.business[period];
  document.getElementById('business-billing').textContent = billingNote;
  // Update Business + AI card price
  document.getElementById('ai-price').textContent = '$' + prices.ai[period];
  document.getElementById('ai-billing').textContent = billingNote;
}
```

Add id="business-price", id="business-billing", id="ai-price", id="ai-billing" to the appropriate elements in the plan cards.

### 2. Team Size Slider
```
const slider = document.getElementById('team-slider');
const sizeValue = document.getElementById('team-size-value');
const recommendation = document.getElementById('team-recommendation');

slider.addEventListener('input', () => {
  const size = parseInt(slider.value);
  sizeValue.textContent = size;
  if (size <= 5) recommendation.textContent = 'Starter plan is perfect for small teams';
  else if (size <= 25) recommendation.textContent = 'Business plan recommended for growing teams';
  else if (size <= 50) recommendation.textContent = 'Business + AI plan recommended for your team size';
  else recommendation.textContent = 'Enterprise plan recommended for large organizations';
});
```

### 3. FAQ Accordion
```
document.querySelectorAll('.faq-question').forEach(btn => {
  btn.addEventListener('click', () => {
    const item = btn.closest('.faq-item');
    const wasActive = item.classList.contains('active');
    document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('active'));
    if (!wasActive) item.classList.add('active');
  });
});
```

### 4. Comparison Table Toggle
```
const toggleBtn = document.querySelector('.comparison-toggle-btn');
const hiddenRows = document.querySelectorAll('.comparison-hidden');
let expanded = false;

toggleBtn.addEventListener('click', () => {
  expanded = !expanded;
  hiddenRows.forEach(row => row.classList.toggle('show', expanded));
  toggleBtn.classList.toggle('expanded', expanded);
  toggleBtn.querySelector('span').textContent = expanded ? 'Show less' : 'See all features';
});
```

### 5. Mobile menu toggle

## Important
- All inline SVGs, no external files
- Semantic HTML5
- Relative paths for all links
- Must work in browser with no build step
- Complete valid HTML document
- The pricing interactivity is the most critical part — ensure toggle correctly updates prices, slider updates recommendation, FAQ accordion opens/closes, and comparison table expands/collapses

